package com.gustavguide.engine.condition;

import com.gustavguide.engine.ConditionContext;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class AndCondition implements Condition
{
	private final List<Condition> conditions;

	public AndCondition(List<Condition> conditions)
	{
		this.conditions = conditions;
	}

	@Override
	public boolean isMet(ConditionContext ctx)
	{
		for (Condition c : conditions)
		{
			if (!c.isMet(ctx))
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public String describe()
	{
		return "(" + conditions.stream().map(Condition::describe).collect(Collectors.joining(" AND ")) + ")";
	}

	@Override
	public Set<Integer> itemIds()
	{
		Set<Integer> ids = new HashSet<>();
		for (Condition c : conditions)
		{
			ids.addAll(c.itemIds());
		}
		return ids;
	}
}

