package com.gustavguide.overlay;

import com.gustavguide.GustavGuideConfig;
import com.gustavguide.GustavGuideState;
import com.gustavguide.engine.RouteStep;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Highlights the item the current step wants you to get/use, wherever it appears — inventory, bank,
 * equipment, and the SHOP stock interface (so "Buy X from Y" outlines X in the shop) — the
 * Quest-Helper-style item marker. Read-only rendering; never interacts with items.
 */
public class GustavItemOverlay extends WidgetItemOverlay
{
	private final GustavGuideConfig config;
	private final GustavGuideState state;

	@Inject
	public GustavItemOverlay(GustavGuideConfig config, GustavGuideState state)
	{
		this.config = config;
		this.state = state;
		showOnInventory();
		showOnBank();
		showOnEquipment();
		showOnInterfaces(InterfaceID.SHOPMAIN);  // 300 — the shop's stock grid
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		// This runs for EVERY highlighted interface slot (inventory + bank + equipment + shop stock)
		// every frame. Keep the hot path to a volatile read + int compares; only touch the config proxy
		// for the one matching item — otherwise a full bank at 50fps floods the client thread and
		// freezes the game.
		RouteStep step = state.getCurrentStep();
		if (step == null)
		{
			return;
		}
		// Highlight EVERY item the step wants — an "Inventory check: A, B, C" step lists them all as
		// requirements, so the whole checklist lights up, not just one item. wantsItem() is a boxing-free
		// int scan over a precomputed array, keeping this per-slot/per-frame path allocation-free.
		if (!step.wantsItem(itemId))
		{
			return;
		}
		if (!config.highlightItems())
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}
		Color color = config.highlightColor();
		graphics.setColor(color);
		graphics.draw(bounds);
		// alpha 60: dialogue/item boxes use a stronger fill than the world tile (40), on purpose
		graphics.setColor(OverlayColors.translucent(color, 60));
		graphics.fill(bounds);
	}
}

